const items = $input.all();

const keywordPatterns = [
  /\bai\b/i,
  /\bartificial intelligence\b/i,
  /\bopenai\b/i,
  /\bchatgpt\b/i,
  /\banthropic\b/i,
  /\bclaude\b/i,
  /\bgemini\b/i,
  /\bcopilot\b/i,
  /\bllm\b/i,
  /\bllms\b/i,
  /\bai agent\b/i,
  /\bagentic\b/i,
  /\bautomation\b/i,
  /\bmachine learning\b/i,
  /\bnvidia\b/i,
  /\brobot\b/i,
  /\bneural\b/i
];

function stripHtml(value) {
  return String(value || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/https?:\/\//g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function getText(item) {
  return [
    item.json.title,
    item.json.contentSnippet,
    item.json.summary,
    item.json.content,
    item.json.link
  ]
    .filter(Boolean)
    .map(stripHtml)
    .join(' ');
}

function isRelevant(item) {
  const text = getText(item);
  return keywordPatterns.some((pattern) => pattern.test(text));
}

function getScore(text) {
  const lower = text.toLowerCase();

  if (
    lower.includes('openai') ||
    lower.includes('chatgpt') ||
    lower.includes('anthropic') ||
    lower.includes('claude') ||
    lower.includes('gemini') ||
    lower.includes('nvidia')
  ) {
    return 84;
  }

  if (
    lower.includes('artificial intelligence') ||
    lower.includes('ai agent') ||
    lower.includes('agentic') ||
    lower.includes('machine learning')
  ) {
    return 78;
  }

  return 68;
}

const relevantItems = items.filter(isRelevant);

return relevantItems.map((item) => {
  const title = stripHtml(item.json.title || 'Unbenannter RSS-Trend');
  const link = item.json.link || '';
  const pubDate = item.json.pubDate || item.json.isoDate || '';
  const text = getText(item);
  const cleanSummary = stripHtml(
    item.json.contentSnippet ||
    item.json.summary ||
    item.json.content ||
    title
  );

  const score = getScore(text);

  return {
    json: {
      id: slugify(link || title),
      name: title,
      category: 'AI News',
      status: score >= 80 ? 'Hohe Relevanz' : 'Beobachten',
      score,
      businessImpact: `Dieses RSS-Signal kann für Marktbeobachtung, Produktstrategie oder Innovation relevant sein: ${title}`,
      summary: cleanSummary.slice(0, 350),
      recommendation: 'Signal prüfen, Relevanz bewerten und bei Bedarf für das Trend-Radar priorisieren.',
      source: 'The Verge RSS',
      timeframe: pubDate ? 'RSS Import' : 'Unbekannt',
      signalType: 'RSS'
    }
  };
});

const requiredFields = [
  'id',
  'name',
  'category',
  'status',
  'score',
  'businessImpact',
  'summary',
  'recommendation',
  'source',
  'timeframe',
  'signalType'
];

return items.map((item) => {
  const normalized = {};

  for (const field of requiredFields) {
    normalized[field] = item.json[field] ?? '';
  }

  normalized.id = String(normalized.id || '').trim();
  normalized.name = String(normalized.name || '').trim();
  normalized.category = String(normalized.category || 'AI News').trim();
  normalized.status = String(normalized.status || 'Neu').trim();
  normalized.score = Math.max(0, Math.min(100, Number(normalized.score) || 0));

  return { json: normalized };
}).filter((item) => item.json.id && item.json.name);

const candidates = $('Trend-Daten normalisieren').all();
const existingRows = $('Bestehende Trends lesen').all();

const existingIds = new Set(
  existingRows
    .map((item) => String(item.json.id || '').trim())
    .filter(Boolean)
);

const newTrends = candidates.filter((item) => {
  const id = String(item.json.id || '').trim();
  return id && !existingIds.has(id);
});

return newTrends;
